cd /workspace && node -e "
const db = require('better-sqlite3')('./world.db');

// Perform the item modification
// 1. Update the order item
db.prepare(\"UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE order_id = ? AND item_id = ?\")
  .run('2364909101', 53.89, JSON.stringify({color: 'Olive', size: 'M'}), '#W4705780', '9716794911');

// 2. Update order status
db.prepare(\"UPDATE orders SET status = ? WHERE order_id = ?\")
  .run('pending (item modified)', '#W4705780');

// 3. Add payment record for the price difference (refund of 1.10)
const diff = 53.89 - 54.99; // -1.10
db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)\")
  .run('#W4705780', 'refund', Math.abs(Math.round(diff * 100) / 100), 'credit_card_5360334');

// Verify the changes
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('#W4705780');
console.log('=== UPDATED ORDER ===');
console.log('order_id:', order.order_id);
console.log('status:', order.status);

const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = ?\").all('#W4705780');
console.log('\n=== UPDATED ITEMS ===');
items.forEach(i => {
  console.log('item_id:', i.item_id, '| name:', i.name, '| price:', i.unit_price, '| options:', i.options);
});

const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = ?\").all('#W4705780');
console.log('\n=== UPDATED PAYMENT HISTORY ===');
payments.forEach(p => {
  console.log('type:', p.transaction_type, '| amount:', p.amount, '| method:', p.payment_method_id);
});
"
